class Vehicle {
  constructor(type, speed) {
    this.type = type;
    this.speed = speed;
  }

  move() {
    return `${this.type} moves at ${this.speed} km/h`;
  }

  static info() {
    return 'Vehicles transport people and goods';
  }
}

class Car extends Vehicle {
  constructor(brand, speed) {
    super('Car', speed);
    this.brand = brand;
  }

  honk() {
    return `${this.brand} goes Beep!`;
  }
}

const car = new Car('Tesla', 200);
console.log(car.move());
console.log(car.honk());
